import os, platform, runpy, shutil, sys, time
from pathlib import Path
if sys.platform != 'linux' or platform.machine().lower() not in ('x86_64', 'amd64'):
    raise SystemExit(f'ENVIRONMENT: the 30s comparison requires Linux x86-64; got {sys.platform}/{platform.machine()}')
if sys.implementation.name != 'cpython' or sys.version_info[:2] != (3, 12):
    executable = shutil.which('python3.12')
    if executable and len(sys.argv) == 1:
        script = sys.orig_argv[sys.orig_argv.index('-c') + 1]
        os.execv(executable, [executable, '-B', '-S', '-c', script, 'reexec'])
    raise SystemExit(f'ENVIRONMENT: benchmark requires CPython 3.12; available interpreter is {sys.implementation.name} {platform.python_version()}')
sys.path.insert(0, str(Path('src').resolve()))
from wafer_fusion import process_calibrated
print(f'Benchmark environment: {platform.system()} {platform.machine()} CPython {platform.python_version()}', flush=True)

def severity(index, x, y):
    if x == 0 and y == 0:
        return 0
    if index < 2 and abs(x) + abs(y) == 1:
        return 0 if ((x, y) == (1, 0)) == (index == 0) else 2
    residue = (13 * x + 7 * y + (index + 1) * x * y + 11 * index) % 23
    return 2 if residue == 0 else 1 if residue == 1 else 0

matrices = {matrix for first in (-1, 1) for second in (-1, 1) for matrix in ((first, 0, 0, second), (0, first, second, 0))}
canonical = [(x, y) for y in range(-70, 71) for x in range(-70, 71)]
local_sites = {(x, y) for y in range(-49, 50) for x in range(-49, 50)}
status_code = {'pass': 0, 'skip': 1, 'fail': 2}
data = runpy.run_path('tests/scale_regression.py')['build_payload']()
assert len(data['sites']) == 19881 and set(map(tuple, data['sites'])) == set(canonical), 'scale builder: complete canonical square required'
assert len(data['runs']) == 20, 'scale builder: 20 required stations'
rids = [run['id'] for run in data['runs']]
assert len(set(rids)) == 20, 'scale builder: run IDs must be distinct'
expected_support = []
for index, run in enumerate(data['runs']):
    got_matrices = {tuple(value for row in candidate['matrix'] for value in row) for candidate in run['candidates']}
    ids = sorted(candidate['id'] for candidate in run['candidates'])
    assert len(ids) == len(set(ids)) == 8 and got_matrices == matrices and all(candidate['offset'] == [0, 0] for candidate in run['candidates']), ('scale builder: D4 transforms', index)
    expected_support.append({'run': run['id'], 'candidates': ids})
    records = {tuple(record['at']): status_code[run['bins'][record['bin']]] for record in run['records']}
    assert len(run['records']) == 9801 and records.keys() == local_sites, ('scale builder: complete local square', index)
    for (x, y), actual in records.items():
        assert actual == severity(index, x, y), ('scale builder: raw disposition', index, (x, y), actual, severity(index, x, y))
expected_links = {(rids[left], (0, 0), rids[right], (0, 0)) for right in range(20) for left in range(max(0, right - 2), right)}
expected_links.add((rids[0], (1, 0), rids[1], (1, 0)))
actual_links = {(link['left']['run'], tuple(link['left']['at']), link['right']['run'], tuple(link['right']['at'])) for link in data['links']}
assert len(data['links']) == 38 and actual_links == expected_links, ('scale builder: 19 gap-one + 18 gap-two + 1 axial link', len(data['links']))

start = time.process_time()
result = process_calibrated(data)
elapsed = time.process_time() - start
print(f'CALIBRATED_API_CPU_SECONDS={elapsed:.6f} (limit 30)', flush=True)

# All origin links are tautologies. Stations 0 and 1 must share the first column, i.e. the image of local [1,0]. Stations 2-19 are independent. Each transform is supported by using an identical partner at the first two stations.
groups = {direction: [matrix for matrix in matrices if (matrix[0], matrix[2]) == direction] for direction in ((1, 0), (-1, 0), (0, 1), (0, -1))}
names = ('pass', 'incomplete', 'fail')

def possible(x, y):
    if max(abs(x), abs(y)) > 49:
        return ['incomplete']
    values = set()
    for group in groups.values():
        first = {severity(0, a*x + c*y, b*x + d*y) for a, b, c, d in group}
        second = {severity(1, a*x + c*y, b*x + d*y) for a, b, c, d in group}
        values.update(max(left, right) for left in first for right in second)
    for index in range(2, 20):
        current = {severity(index, a*x + c*y, b*x + d*y) for a, b, c, d in matrices}
        values = {max(left, right) for left in values for right in current}
    return [names[status] for status in sorted(values)]

assert set(result) == {'schema', 'wafer', 'supported_candidates', 'dies', 'pick_coordinates'} and result['schema'] == 'wafer-calibration-v1' and result['wafer'] == data['wafer'], 'scale output envelope'
assert result['supported_candidates'] == expected_support, ('scale: incorrect support or station order', result['supported_candidates'])
assert isinstance(result['dies'], list) and len(result['dies']) == 19881, 'scale: missing or extra die rows'
expected_picks = []
wafer = data['wafer']
edge_count = 0
for got, (x, y) in zip(result['dies'], canonical):
    states = possible(x, y)
    want = {'die_id': f'{wafer}:{x}:{y}', 'at': [x, y], 'possible_statuses': states}
    assert got == want, ('scale die mismatch', (x, y), got, want)
    if x == 0 and y == 0:
        assert got['possible_statuses'] == ['pass'], 'origin must always pass'
    elif abs(x) + abs(y) == 1:
        assert got['possible_statuses'] == ['fail'], ('first-pair axial complement', (x, y))
    elif max(abs(x), abs(y)) > 49:
        assert got['possible_statuses'] == ['incomplete'], ('outside local square', (x, y))
        edge_count += 1
    if states == ['pass']:
        expected_picks.append([x, y])
assert edge_count == 10080 and [0, 0] in expected_picks, 'scale sentinel coverage'
assert result['pick_coordinates'] == expected_picks, ('scale pick list mismatch', len(result['pick_coordinates']), len(expected_picks))
assert elapsed <= 30.0, f'API process CPU budget exceeded: {elapsed:.6f}s > 30.0s on CPython {platform.python_version()}'
print(f'Scale verified: {len(canonical)} exact ordered rows, 20 complete support lists, {len(expected_picks)} picks; 196020 records and 38 links')
